return $input.all().map(i => {
  const name = String(i.json.name || '').trim();
  const isProject = /^TATTOO_\d{4}$/i.test(name);
  const isContainer = !isProject && /^\d{4}$/.test(name);
  return { json: {
    ...i.json,
    molotov_type: isProject ? 'PROJECT' : isContainer ? 'CONTAINER' : 'IGNORE',
    project_id: isProject ? name.toUpperCase() : null,
    project_folder_id: isProject ? i.json.id : null,
    discovered_at: new Date().toISOString()
  }};
});

return $input.all()
  .filter(i => /^TATTOO_\d{4}$/i.test(String(i.json.name || '').trim()))
  .map(i => ({ json: {
    ...i.json,
    molotov_type: 'PROJECT',
    project_id: String(i.json.name).trim().toUpperCase(),
    project_folder_id: i.json.id,
    discovered_at: new Date().toISOString()
  }}));

// MOLOTOV SOCIAL OS — MULTIPROJECT LINKED NORMALIZATION
// IMPORTANT:
// We do not infer the project from Drive metadata.
// n8n already links each LIST — PROJECT MEDIA output item back to the
// PREPARE — PROJECT CONTEXT item that generated it.
// itemMatching(index) is the supported way to retrieve that linked item.

const inputItems = $input.all();

function extension(name) {
  const parts = String(name || '').split('.');
  return parts.length > 1 ? parts.pop().toLowerCase() : '';
}

function mediaType(name) {
  const ext = extension(name);

  if ([
    'jpg', 'jpeg', 'png', 'webp',
    'heic', 'heif', 'tif', 'tiff'
  ].includes(ext)) return 'IMAGE';

  if ([
    'mp4', 'mov', 'm4v', 'avi',
    'mkv', 'webm'
  ].includes(ext)) return 'VIDEO';

  return 'OTHER';
}

return inputItems.map((item, index) => {
  const file = item.json;

  // Trace THIS specific media item back to the project item that caused
  // Google Drive to return it.
  const linkedProject =
    $('PREPARE — PROJECT CONTEXT').itemMatching(index)?.json;

  if (!linkedProject?.project_id || !linkedProject?.project_folder_id) {
    throw new Error(
      `PROJECT_LINK_NOT_FOUND: arquivo=${file.name || file.id} index=${index}`
    );
  }

  const type = mediaType(file.name);

  return {
    json: {
      project_id: linkedProject.project_id,
      project_folder_id: linkedProject.project_folder_id,

      drive_file_id: file.id,
      file_name: file.name,
      extension: extension(file.name),

      media_type: type,
      is_supported_media:
        type === 'IMAGE' || type === 'VIDEO',

      source: 'GOOGLE_DRIVE',
      storage_status: 'ONLINE',
      ingestion_status: 'DISCOVERED',

      ingestion_key: `gdrive:${file.id}`,

      discovery_index: index + 1,
      discovered_at: new Date().toISOString()
    },

    // Explicitly preserve the link between each normalized media item
    // and its corresponding LIST — PROJECT MEDIA input item.
    pairedItem: {
      item: index
    }
  };
});

const discovered = $('NORMALIZE — MEDIA').all().map(i => i.json);
const existing = $input.all().map(i => i.json);

function extractDriveId(url) {
  if (!url) return null;
  for (const r of [/\/file\/d\/([^/]+)/, /[?&]id=([^&]+)/, /\/d\/([^/]+)/]) {
    const m = String(url).match(r);
    if (m?.[1]) return m[1];
  }
  return null;
}

const driveIds = new Set();
const projectNames = new Set();

for (const row of existing) {
  const d = extractDriveId(row.LINK_DRIVE);
  if (d) driveIds.add(d);
  const pid = String(row.ID_PROJETO || '').trim().toUpperCase();
  const fn = String(row.ARQUIVO || '').trim().toLowerCase();
  if (pid && fn) projectNames.add(`${pid}::${fn}`);
}

return discovered.map(a => {
  const scoped = `${String(a.project_id || '').toUpperCase()}::${String(a.file_name || '').trim().toLowerCase()}`;
  const byDrive = Boolean(a.drive_file_id && driveIds.has(a.drive_file_id));
  const byScopedName = Boolean(a.project_id && a.file_name && projectNames.has(scoped));
  const exists = byDrive || byScopedName;
  return { json: {
    ...a,
    already_exists: exists,
    match_method: byDrive ? 'DRIVE_ID' : byScopedName ? 'PROJECT_FILE_NAME' : 'NONE',
    ingestion_action: exists ? 'SKIP' : 'INSERT'
  }};
});

const items = $input.all().map(i => i.json);
const stats = {};
for (const x of items) {
  const p = x.project_id || 'NO_PROJECT';
  stats[p] ??= {total:0, INSERT:0, SKIP:0};
  stats[p].total++;
  stats[p][x.ingestion_action] = (stats[p][x.ingestion_action] || 0) + 1;
}
return items.map(x => ({json:{...x, isolation_audit: stats}}));

// MOLOTOV SOCIAL OS — PRE-WRITE DRY RUN
// Does NOT write anything. It builds the exact project/media rows that a later
// production version would append.

const projectRows = $input.all().map(i => i.json);
const projectContexts = $('PREPARE — PROJECT CONTEXT').all().map(i => i.json);
const media = $('AUDIT — PROJECT ISOLATION').all().map(i => i.json);
const existingMediaRows = $('READ — 03_MIDIAS').all().map(i => i.json);

const existingProjects = new Set(
  projectRows
    .map(r => String(r.ID_PROJETO || '').trim().toUpperCase())
    .filter(Boolean)
);

const uniqueProjects = new Map();
for (const p of projectContexts) {
  const id = String(p.project_id || '').trim().toUpperCase();
  if (!id) continue;
  uniqueProjects.set(id, p);
}

const newProjects = [];
for (const [id, p] of uniqueProjects.entries()) {
  if (existingProjects.has(id)) continue;

  newProjects.push({
    ID_PROJETO: id,
    NOME: id,
    TIPO: 'Tattoo',
    STATUS: 'EM TRIAGEM',
    SESSÕES: '',
    DATA_INICIAL: '',
    DATA_FINAL: '',
    PASTA_BRUTOS: `https://drive.google.com/drive/folders/${p.project_folder_id}`,
    'ANÁLISE_VISUAL': 'PENDENTE',
    PRIORIDADE: '',
    'OBSERVAÇÕES': 'Cadastro automático de projeto descoberto em 00_BRUTOS.',
    ATUALIZADO_EM: new Date().toISOString().slice(0, 10)
  });
}

// Find the current highest Mxxxx identifier without assuming the sheet is perfectly ordered.
let maxMediaNumber = 0;
for (const r of existingMediaRows) {
  const m = String(r.ID_MIDIA || '').trim().match(/^M(\d+)$/i);
  if (m) maxMediaNumber = Math.max(maxMediaNumber, Number(m[1]));
}

const inserts = media.filter(m => m.ingestion_action === 'INSERT');

const mediaRows = inserts.map((m, index) => {
  const id = `M${String(maxMediaNumber + index + 1).padStart(4, '0')}`;

  return {
    ID_MIDIA: id,
    ID_PROJETO: m.project_id,
    ARQUIVO: m.file_name,
    LINK_DRIVE: `https://drive.google.com/file/d/${m.drive_file_id}/view`,
    TIPO: m.media_type === 'IMAGE' ? 'FOTO' : m.media_type === 'VIDEO' ? 'VIDEO' : m.media_type,
    DATA_CAPTURA: '',
    'SESSÃO': '',
    TAMANHO: '',
    TRIAGEM: 'PENDENTE',
    QUALIDADE: '',
    'CONTEÚDO_VISUAL': '',
    MELHOR_TRECHO: '',
    USAR_EM: '',
    'OBSERVAÇÕES': `Ingestão automática; drive_file_id=${m.drive_file_id}`
  };
});

return [{
  json: {
    dry_run: true,
    safe_to_write: false,
    generated_at: new Date().toISOString(),
    summary: {
      discovered_projects: uniqueProjects.size,
      existing_projects: existingProjects.size,
      new_projects_to_insert: newProjects.length,
      media_total_discovered: media.length,
      media_existing_skip: media.filter(m => m.ingestion_action === 'SKIP').length,
      media_new_to_insert: mediaRows.length,
      next_media_id_start: mediaRows.length ? mediaRows[0].ID_MIDIA : null,
      next_media_id_end: mediaRows.length ? mediaRows[mediaRows.length - 1].ID_MIDIA : null
    },
    project_rows_to_insert: newProjects,
    media_rows_to_insert: mediaRows
  }
}];
